class _AdPromoRedeemCardState extends ConsumerState<AdPromoRedeemCard> {
  final controller = TextEditingController();
  bool saving = false;
  @override void dispose() { controller.dispose(); super.dispose(); }
  @override Widget build(BuildContext context) => HBCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('p42.ads_promo.title'.tr(), style: context.textStyles.titleMedium), const SizedBox(height: AppSpacing.xs), Text('p42.ads_promo.help'.tr()), const SizedBox(height: AppSpacing.sm), Row(children: [Expanded(child: HBInput(controller: controller, hint: 'p42.ads_promo.placeholder'.tr())), const SizedBox(width: AppSpacing.sm), HBButton.primary(label: 'p42.ads_promo.redeem'.tr(), isLoading: saving, onPressed: saving ? null : redeem)])]));
  Future<void> redeem() async { if (controller.text.trim().isEmpty) return; setState(() => saving = true); try { final result = await ref.read(adsRepositoryProvider).redeemPromoCode(widget.accountId, controller.text); ref.invalidate(adAccountBillingProvider(widget.accountId)); if (mounted) { controller.clear(); final amount = MoneyFormatter.format(amountMinor: (result['credit_minor'] as num?)?.toInt() ?? 0, currencyCode: result['currency_code']?.toString() ?? widget.currencyCode, locale: context.locale); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('p42.ads_promo.success'.tr(namedArgs: {'amount': amount})))); } } on AppException catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error.messageKey.tr()))); } finally { if (mounted) setState(() => saving = false); } }
}

