String _major(int minor) => '${minor ~/ 100},${(minor % 100).toString().padLeft(2, '0')}';
int _minor(String input) { final parts = input.trim().replaceAll(',', '.').split('.'); final major = int.tryParse(parts.first) ?? 0; final cents = parts.length > 1 ? int.tryParse(parts[1].padRight(2, '0').substring(0, 2)) ?? 0 : 0; return major * 100 + cents; }